pub const DOCUMENTS: &[&str] = &["combat", "gameoptions", "civbuilder", "civpowers", "aipersonalities"];

pub fn encode_top(r: &crate::rules::Rules, out: &mut Vec<u8>) {
    r.combat.encode(out);
    r.game_options.encode(out);
    r.civ_builder.encode(out);
    r.civ_powers.encode(out);
    r.ai_personalities.encode(out);
    enc_len(out, r.epochs.len()); for x in &r.epochs { x.encode(out); }
    enc_bool(out, r.epoch_music_from_text);
}
